fn is_digit::(s) {
    if (@len(s) == 0) { return false; }
    for c in s {
        if (c < "0" || c > "9") { return false; }
    }
    return true;
}

fn is_alpha::(s) {
    if (@len(s) == 0) { return false; }
    for c in s {
        let lc = @lower(c);
        if (lc < "a" || lc > "z") { return false; }
    }
    return true;
}

fn is_space::(c) {
    return c == " " || c == "\t" || c == "\n" || c == "\r";
}

fn strip::(s) {
    let i = 0;
    while (i < @len(s) && is_space(@substr(s, i, 1))) { i = i + 1; }
    let j = @len(s);
    while (j > i && is_space(@substr(s, j - 1, 1))) { j = j - 1; }
    return @substr(s, i, j - i);
}

fn lstrip::(s) {
    let i = 0;
    while (i < @len(s) && is_space(@substr(s, i, 1))) { i = i + 1; }
    return @substr(s, i);
}

fn rstrip::(s) {
    let j = @len(s);
    while (j > 0 && is_space(@substr(s, j - 1, 1))) { j = j - 1; }
    return @substr(s, 0, j);
}

fn capitalize::(s) {
    if (@len(s) == 0) { return ""; }
    return @upper(@substr(s, 0, 1)) + @lower(@substr(s, 1));
}

fn title::(s) {
    let parts = @split(s, " ");
    let out = [];
    for p in parts { @push(out, capitalize(p)); }
    return @join(out, " ");
}

fn words::(s) {
    let parts = @split(strip(s), " ");
    let out = [];
    for p in parts {
        if (@len(p) > 0) { @push(out, p); }
    }
    return out;
}

fn reverse::(s) {
    let out = "";
    let i = @len(s) - 1;
    while (i >= 0) {
        out = out + @substr(s, i, 1);
        i = i - 1;
    }
    return out;
}

fn is_palindrome::(s) {
    let t = @lower(s);
    return t == reverse(t);
}

fn count::(s, sub) {
    let n = 0;
    let i = 0;
    while (i + @len(sub) <= @len(s)) {
        if (@substr(s, i, @len(sub)) == sub) {
            n = n + 1;
            i = i + @len(sub);
        } else {
            i = i + 1;
        }
    }
    return n;
}

fn pad_left::(s, n, ch) {
    while (@len(s) < n) { s = ch + s; }
    return s;
}

fn pad_right::(s, n, ch) {
    while (@len(s) < n) { s = s + ch; }
    return s;
}

fn starts_with::(s, pre) {
    return @len(s) >= @len(pre) && @substr(s, 0, @len(pre)) == pre;
}

fn ends_with::(s, suf) {
    return @len(s) >= @len(suf) && @substr(s, @len(s) - @len(suf)) == suf;
}
